final class TruckService
{
 private const BODY_TYPES=['FLATBED','BOX','CURTAIN_SIDE','TIPPER','TANKER','REFRIGERATED','CONTAINER_CARRIER','OTHER'];
 private const CAPACITY_UNITS=['KG','TONNE','M3'];
 public static function bodyTypes():array{return self::BODY_TYPES;}
 public static function capacityUnits():array{return self::CAPACITY_UNITS;}
 private static function ownerContext():array
 {
  if(!Auth::hasRole('TRUCK_OWNER'))throw new RuntimeException('An active Carrier role is required.');$userId=(int)Auth::user()['id'];$profile=CarrierOnboarding::current($userId);
  if(!$profile||$profile['verification_status']!=='verified'||$profile['case_status']!=='approved')throw new RuntimeException('Carrier verification must be approved before registering trucks.');
  return['user_id'=>$userId,'owner_type'=>$profile['owner_type'],'owner_company_id'=>$profile['owner_type']==='company'?(int)$profile['subject_id']:null,'owner_user_id'=>$profile['owner_type']==='individual'?$userId:null];
 }
 private static function ownerWhere(array$owner,string$alias='t'):array
 {
  return $owner['owner_company_id']?["{$alias}.owner_company_id=?",[$owner['owner_company_id']]]:["{$alias}.owner_user_id=?",[$owner['owner_user_id']]];
 }
 public static function counts():array
 {
  $owner=self::ownerContext();[$where,$params]=self::ownerWhere($owner);$st=Database::connection()->prepare("SELECT COUNT(*) total,SUM(t.verification_status='pending') pending,SUM(t.verification_status='verified') verified,SUM(t.verification_status='rejected') rejected FROM trucks t WHERE {$where} AND t.status='active'");$st->execute($params);$r=$st->fetch();return['total'=>(int)($r['total']??0),'pending'=>(int)($r['pending']??0),'verified'=>(int)($r['verified']??0),'rejected'=>(int)($r['rejected']??0)];
 }
 public static function allOwn():array
 {
  if(!Auth::can('TRUCK_VIEW_OWN'))throw new RuntimeException('Truck view permission is required.');$owner=self::ownerContext();[$where,$params]=self::ownerWhere($owner);$sql="SELECT t.truck_id,t.truck_ref,t.registration_number,t.registration_country,t.make_name,t.model_name,t.body_type_code,t.capacity_value,t.capacity_unit,t.availability_status,t.verification_status,t.created_at FROM trucks t WHERE {$where} AND t.status='active' ORDER BY t.created_at DESC";$st=Database::connection()->prepare($sql);$st->execute($params);return$st->fetchAll();
 }
 public static function findOwn(int$id):?array
 {
  if(!Auth::can('TRUCK_VIEW_OWN'))return null;$owner=self::ownerContext();[$where,$params]=self::ownerWhere($owner);$sql="SELECT t.*,i.inspection_id,i.inspection_number,i.inspected_on,i.expires_on inspection_expires_on,i.result_code,i.roadworthiness_status,ip.insurance_policie_id,ip.policy_number,ip.provider_name,ip.valid_from insurance_valid_from,ip.valid_to insurance_valid_to,ip.coverage_type,vc.verification_case_id,vc.status case_status,vc.findings FROM trucks t LEFT JOIN inspections i ON i.truck_id=t.truck_id AND i.status='active' LEFT JOIN insurance_policy_links il ON il.truck_id=t.truck_id AND il.status='active' LEFT JOIN insurance_policies ip ON ip.insurance_policie_id=il.insurance_policy_id AND ip.status='active' LEFT JOIN verification_cases vc ON vc.truck_id=t.truck_id AND vc.case_type='truck_verification' WHERE t.truck_id=? AND {$where} AND t.status='active' ORDER BY vc.verification_case_id DESC LIMIT 1";$st=Database::connection()->prepare($sql);$st->execute(array_merge([$id],$params));$r=$st->fetch();return$r?:null;
 }
 private static function date(mixed$value,string$label):string{$value=trim((string)$value);$dt=\DateTimeImmutable::createFromFormat('!Y-m-d',$value,new \DateTimeZone('UTC'));if(!$dt||$dt->format('Y-m-d')!==$value)throw new RuntimeException("{$label} must be a valid date.");return$value;}
 private static function clean(array$d):array
 {
  $reg=strtoupper(trim((string)($d['registration_number']??'')));$country=strtoupper(trim((string)($d['registration_country']??'')));$make=trim((string)($d['make_name']??''));$model=trim((string)($d['model_name']??''));$chassis=strtoupper(trim((string)($d['chassis_number']??'')));$engine=strtoupper(trim((string)($d['engine_number']??'')));$body=strtoupper(trim((string)($d['body_type_code']??'')));$unit=strtoupper(trim((string)($d['capacity_unit']??'')));$capacity=(float)($d['capacity_value']??0);$year=(int)($d['manufacture_year']??0);
  if($reg===''||!preg_match('/^[A-Z]{2}$/',$country)||$make===''||$model===''||$chassis==='')throw new RuntimeException('Registration, country, make, model, and chassis number are required.');if(!in_array($body,self::BODY_TYPES,true)||!in_array($unit,self::CAPACITY_UNITS,true))throw new RuntimeException('Choose an approved body type and capacity unit.');if($capacity<=0)throw new RuntimeException('Capacity must be greater than zero.');$maxYear=(int)gmdate('Y')+1;if($year<1900||$year>$maxYear)throw new RuntimeException('Manufacture year is outside the accepted range.');
  $policy=trim((string)($d['policy_number']??''));$provider=trim((string)($d['provider_name']??''));$coverage=trim((string)($d['coverage_type']??''));$validFrom=self::date($d['insurance_valid_from']??null,'Insurance start');$validTo=self::date($d['insurance_valid_to']??null,'Insurance expiry');if($policy===''||$provider===''||$coverage==='')throw new RuntimeException('Insurance provider, policy number, and coverage type are required.');if($validTo<$validFrom)throw new RuntimeException('Insurance expiry cannot be before its start date.');
  $inspection=trim((string)($d['inspection_number']??''));$inspectedOn=self::date($d['inspected_on']??null,'Inspection date');$expiresOn=self::date($d['inspection_expires_on']??null,'Inspection expiry');$result=strtoupper(trim((string)($d['result_code']??'')));$road=strtoupper(trim((string)($d['roadworthiness_status']??'')));if($inspection===''||!in_array($result,['PASS','FAIL'],true)||!in_array($road,['ROADWORTHY','NOT_ROADWORTHY'],true))throw new RuntimeException('Inspection reference, result, and roadworthiness result are required.');if($expiresOn<$inspectedOn)throw new RuntimeException('Inspection expiry cannot be before the inspection date.');
  $limits=[[$reg,64],[$make,96],[$model,96],[$chassis,96],[$engine,96],[$policy,96],[$provider,191],[$coverage,96],[$inspection,96]];foreach($limits as[$value,$max])if(strlen($value)>$max)throw new RuntimeException('One or more truck fields exceed the approved length.');return compact('reg','country','make','model','chassis','engine','body','unit','capacity','year','policy','provider','coverage','validFrom','validTo','inspection','inspectedOn','expiresOn','result','road');
 }
 public static function create(array$data,int$userId):int
 {
  if(!Auth::can('TRUCK_CREATE_OWN'))throw new RuntimeException('Truck creation permission is required.');$owner=self::ownerContext();if($owner['user_id']!==$userId)throw new RuntimeException('Invalid owner context.');$d=self::clean($data);$pdo=Database::connection();$pdo->beginTransaction();try{
   $st=$pdo->prepare("SELECT COUNT(*) FROM trucks WHERE registration_country=? AND registration_number=? AND status='active'");$st->execute([$d['country'],$d['reg']]);if((int)$st->fetchColumn()>0)throw new RuntimeException('That truck registration already exists.');$st=$pdo->prepare("SELECT COUNT(*) FROM trucks WHERE chassis_number=? AND status='active'");$st->execute([$d['chassis']]);if((int)$st->fetchColumn()>0)throw new RuntimeException('That chassis number already exists.');
   $pdo->prepare("INSERT INTO trucks(truck_ref,owner_company_id,owner_user_id,registration_number,registration_country,make_name,model_name,manufacture_year,chassis_number,engine_number,body_type_code,capacity_value,capacity_unit,availability_status,verification_status,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,'unavailable','pending','active',?,?)")->execute([Reference::make('TRK'),$owner['owner_company_id'],$owner['owner_user_id'],$d['reg'],$d['country'],$d['make'],$d['model'],$d['year'],$d['chassis'],$d['engine']?:null,$d['body'],$d['capacity'],$d['unit'],$userId,$userId]);$truckId=(int)$pdo->lastInsertId();
   $policyMeta=json_encode(['source'=>'carrier_submission'],JSON_THROW_ON_ERROR);$pdo->prepare("INSERT INTO insurance_policies(insurance_policie_ref,policy_number,provider_name,valid_from,valid_to,coverage_type,metadata_json,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,?,?,?,'active',?,?)")->execute([Reference::make('INS'),$d['policy'],$d['provider'],$d['validFrom'],$d['validTo'],$d['coverage'],$policyMeta,$userId,$userId]);$policyId=(int)$pdo->lastInsertId();
   $pdo->prepare("INSERT INTO insurance_policy_links(insurance_policy_link_ref,insurance_policy_id,truck_id,metadata_json,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,'active',?,?)")->execute([Reference::make('IPL'),$policyId,$truckId,json_encode(['link_role'=>'truck'],JSON_THROW_ON_ERROR),$userId,$userId]);
   $inspectionMeta=json_encode(['source'=>'carrier_submission'],JSON_THROW_ON_ERROR);$pdo->prepare("INSERT INTO inspections(inspection_ref,truck_id,inspection_number,inspected_on,expires_on,result_code,roadworthiness_status,metadata_json,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,?,?,?,?, 'active',?,?)")->execute([Reference::make('INP'),$truckId,$d['inspection'],$d['inspectedOn'],$d['expiresOn'],$d['result'],$d['road'],$inspectionMeta,$userId,$userId]);
   $pdo->prepare("INSERT INTO verification_cases(verification_case_ref,case_type,user_id,company_id,truck_id,status,created_by_user_id,updated_by_user_id) VALUES(?,'truck_verification',?,?,?,'pending',?,?)")->execute([Reference::make('VER'),$owner['owner_user_id'],$owner['owner_company_id'],$truckId,$userId,$userId]);$caseId=(int)$pdo->lastInsertId();
   self::history($pdo,$truckId,null,'pending',$userId,self::carrierRoleId(),'Truck submitted for Operations verification');self::audit($pdo,'TRUCK_SUBMITTED',$truckId,$userId,['verification_case_id'=>$caseId]);$pdo->commit();return$truckId;
  }catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}
 }
 public static function reviewQueue():array
 {
  self::requireOperations('TRUCK_REVIEW_QUEUE_VIEW');$sql="SELECT vc.verification_case_id,vc.created_at,t.truck_id,t.truck_ref,t.registration_number,t.registration_country,t.make_name,t.model_name,t.body_type_code,t.capacity_value,t.capacity_unit,u.display_name owner_user_name,c.display_name owner_company_name,i.expires_on inspection_expires_on,i.result_code,i.roadworthiness_status,ip.valid_to insurance_valid_to FROM verification_cases vc JOIN trucks t ON t.truck_id=vc.truck_id LEFT JOIN users u ON u.user_id=t.owner_user_id LEFT JOIN companies c ON c.company_id=t.owner_company_id LEFT JOIN inspections i ON i.truck_id=t.truck_id AND i.status='active' LEFT JOIN insurance_policy_links il ON il.truck_id=t.truck_id AND il.status='active' LEFT JOIN insurance_policies ip ON ip.insurance_policie_id=il.insurance_policy_id AND ip.status='active' WHERE vc.case_type='truck_verification' AND vc.status='pending' ORDER BY vc.created_at";return Database::connection()->query($sql)->fetchAll();
 }
 public static function review(int$caseId):?array
 {
  self::requireOperations('TRUCK_REVIEW_QUEUE_VIEW');$sql="SELECT vc.verification_case_id,vc.status case_status,vc.findings,t.*,u.display_name owner_user_name,c.display_name owner_company_name,i.inspection_number,i.inspected_on,i.expires_on inspection_expires_on,i.result_code,i.roadworthiness_status,ip.policy_number,ip.provider_name,ip.valid_from insurance_valid_from,ip.valid_to insurance_valid_to,ip.coverage_type FROM verification_cases vc JOIN trucks t ON t.truck_id=vc.truck_id LEFT JOIN users u ON u.user_id=t.owner_user_id LEFT JOIN companies c ON c.company_id=t.owner_company_id LEFT JOIN inspections i ON i.truck_id=t.truck_id AND i.status='active' LEFT JOIN insurance_policy_links il ON il.truck_id=t.truck_id AND il.status='active' LEFT JOIN insurance_policies ip ON ip.insurance_policie_id=il.insurance_policy_id AND ip.status='active' WHERE vc.verification_case_id=? AND vc.case_type='truck_verification' LIMIT 1";$st=Database::connection()->prepare($sql);$st->execute([$caseId]);$r=$st->fetch();return$r?:null;
 }
 public static function decide(int$caseId,int$reviewerId,string$decision,string$reason):void
 {
  if(!in_array($decision,['approved','rejected'],true))throw new RuntimeException('Invalid truck decision.');self::requireOperations($decision==='approved'?'TRUCK_REVIEW_APPROVE':'TRUCK_REVIEW_REJECT');$reason=trim($reason);if($decision==='rejected'&&(strlen($reason)<10||strlen($reason)>4000))throw new RuntimeException('Rejection reason must be 10 to 4000 characters.');if($decision==='approved'&&strlen($reason)>2000)throw new RuntimeException('Approval note cannot exceed 2000 characters.');$pdo=Database::connection();$pdo->beginTransaction();try{
   $st=$pdo->prepare("SELECT vc.verification_case_id,vc.status case_status,t.truck_id,t.owner_company_id,t.owner_user_id,t.verification_status,i.expires_on,i.result_code,i.roadworthiness_status,ip.valid_to FROM verification_cases vc JOIN trucks t ON t.truck_id=vc.truck_id JOIN inspections i ON i.truck_id=t.truck_id AND i.status='active' JOIN insurance_policy_links il ON il.truck_id=t.truck_id AND il.status='active' JOIN insurance_policies ip ON ip.insurance_policie_id=il.insurance_policy_id AND ip.status='active' WHERE vc.verification_case_id=? AND vc.case_type='truck_verification' FOR UPDATE");$st->execute([$caseId]);$r=$st->fetch();if(!$r||$r['case_status']!=='pending'||$r['verification_status']!=='pending')throw new RuntimeException('Only a pending truck verification may be decided.');
   if($decision==='approved'&&($r['result_code']!=='PASS'||$r['roadworthiness_status']!=='ROADWORTHY'||$r['expires_on']<gmdate('Y-m-d')||$r['valid_to']<gmdate('Y-m-d')))throw new RuntimeException('Approval requires PASS, ROADWORTHY, and unexpired inspection and insurance references.');
   $new=$decision==='approved'?'verified':'rejected';$st=$pdo->prepare("UPDATE trucks SET verification_status=?,availability_status='unavailable',updated_by_user_id=?,row_version=row_version+1 WHERE truck_id=? AND verification_status='pending'");$st->execute([$new,$reviewerId,$r['truck_id']]);if($st->rowCount()!==1)throw new RuntimeException('Truck verification changed.');$st=$pdo->prepare("UPDATE verification_cases SET status=?,findings=?,assigned_reviewer_user_id=?,updated_by_user_id=?,row_version=row_version+1 WHERE verification_case_id=? AND status='pending'");$st->execute([$decision,$reason!==''?$reason:null,$reviewerId,$reviewerId,$caseId]);if($st->rowCount()!==1)throw new RuntimeException('Verification case changed.');
   self::history($pdo,(int)$r['truck_id'],'pending',$new,$reviewerId,self::operationsRoleId(),$decision==='approved'?'Truck compliance verified; availability remains unavailable':'Truck verification rejected: '.$reason);self::audit($pdo,$decision==='approved'?'TRUCK_VERIFICATION_APPROVED':'TRUCK_VERIFICATION_REJECTED',(int)$r['truck_id'],$reviewerId,['verification_case_id'=>$caseId]);$pdo->commit();if($decision==='approved')try{SubscriptionEligibilityService::recomputeOwner($r['owner_company_id']?(int)$r['owner_company_id']:null,$r['owner_user_id']?(int)$r['owner_user_id']:null,$reviewerId);}catch(\Throwable$eligibilityError){@file_put_contents(BASE_PATH.'/storage/logs/phase6d.log','['.date('c').'] '.$eligibilityError->getMessage().PHP_EOL,FILE_APPEND|LOCK_EX);}
  }catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}
 }
 private static function carrierRoleId():?int{foreach(Auth::context()['roles']??[]as$r)if($r['role_code']==='TRUCK_OWNER')return(int)$r['user_role_id'];return null;}
 private static function operationsRoleId():int{foreach(Auth::context()['roles']??[]as$r)if($r['role_code']==='MCCOLLIN_OPERATIONS')return(int)$r['user_role_id'];throw new RuntimeException('Active Operations role is required.');}
 private static function requireOperations(string$p):void{if(!Auth::hasRole('MCCOLLIN_OPERATIONS')||!Auth::can($p))throw new RuntimeException('Operations truck-review permission is required.');}
 private static function history(PDO$pdo,int$id,?string$old,string$new,int$uid,?int$roleId,string$reason):void{$pdo->prepare("INSERT INTO status_history(status_history_ref,entity_type,entity_id_value,previous_status,new_status,actor_user_id,actor_user_role_id,source_channel,reason,occurred_at,status,created_by_user_id) VALUES(?,'truck',?,?,?,?,?,'web',?,UTC_TIMESTAMP(6),'active',?)")->execute([Reference::make('STH'),$id,$old,$new,$uid,$roleId,$reason,$uid]);}
 private static function audit(PDO$pdo,string$action,int$id,int$uid,array$extra=[]):void{$meta=json_encode(array_merge(['action_code'=>$action,'entity_type'=>'truck','entity_id'=>$id,'source'=>'web'],$extra),JSON_THROW_ON_ERROR);$pdo->prepare("INSERT INTO audit_events(audit_event_ref,metadata_json,status,created_by_user_id) VALUES(?,?,'active',?)")->execute([Reference::make('AUD'),$meta,$uid]);}
}
